import numpy as np
import pandas as pd


TARGET_COLUMN = 'target'


def find_best_stump(X, y):
    """Find best decision stump (feature, threshold, flip) on training data."""
    n, d = X.shape
    best_acc = 0
    best_feat = 0
    best_thresh = 0
    best_flip = False
    for j in range(d):
        vals = np.sort(np.unique(X[:, j]))
        thresholds = (vals[:-1] + vals[1:]) / 2 if len(vals) > 1 else vals
        for t in thresholds:
            for flip in [False, True]:
                if flip:
                    p = (X[:, j] < t).astype(int)
                else:
                    p = (X[:, j] >= t).astype(int)
                acc = (p == y).mean()
                if acc > best_acc:
                    best_acc = acc
                    best_feat = j
                    best_thresh = t
                    best_flip = flip
    return best_feat, best_thresh, best_flip, best_acc


def stump_predict(X, feat, thresh, flip):
    if flip:
        return (X[:, feat] < thresh).astype(int)
    else:
        return (X[:, feat] >= thresh).astype(int)


def loo_stump_accuracy(X, y):
    """LOO-CV for a decision stump."""
    correct = 0
    for i in range(len(X)):
        mask = np.arange(len(X)) != i
        feat, thresh, flip, _ = find_best_stump(X[mask], y[mask])
        pred = stump_predict(X[i:i+1], feat, thresh, flip)
        if pred[0] == y[i]:
            correct += 1
    return correct / len(X)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Decision stump with LOO-CV model selection."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(float)
    y_train = train[TARGET_COLUMN].values.astype(float)
    X_test = test[feature_cols].values.astype(float)

    # Try full stump
    stump_loo = loo_stump_accuracy(X_train, y_train)

    # Majority baseline
    majority_acc = max(y_train.mean(), 1 - y_train.mean())
    majority = int(np.round(y_train.mean()))

    if stump_loo > majority_acc:
        feat, thresh, flip, _ = find_best_stump(X_train, y_train)
        preds = stump_predict(X_test, feat, thresh, flip)
    else:
        preds = np.full(len(X_test), majority)

    predictions = pd.DataFrame({"prediction": preds.astype(int)})
    predictions.to_csv(output_csv, index=False)

